def find_area_by_code(code: str) -> Optional[dict]:
    """Find an area by its code (accepts both '401 001' and '401001' formats)."""
    code_clean = code.replace(" ", "")
    for area in CZECH_AREAS:
        if area["code_clean"] == code_clean:
            return area
    return None


def find_nearest_areas(lat: float, lon: float, max_distance_km: float = 10.0) -> list[dict]:
    """Find all fishing areas within max_distance_km of the given coordinates."""
    results = []
    for area in CZECH_AREAS:
        if area["lat"] is None:
            continue
        dist = _haversine_km(lat, lon, area["lat"], area["lon"])
        if dist <= max_distance_km:
            area_with_dist = {**area, "distance_km": round(dist, 2)}
            results.append(area_with_dist)
    results.sort(key=lambda x: x["distance_km"])
    return results
